package site.hsu.hub.recruitment.adapter.out.persistence;import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="application_forms")public class ApplicationFormEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="recruitment_id",nullable=false,unique=true)private Long recruitmentId;@Column(name="created_at",nullable=false)private Instant createdAt;protected ApplicationFormEntity(){}public ApplicationFormEntity(Long r){recruitmentId=r;createdAt=Instant.now();}public Long id(){return id;}public Long recruitmentId(){return recruitmentId;}}
